CREATE DATABASE IF NOT EXISTS techwise CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE techwise;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, avatar_url VARCHAR(255), role ENUM('admin','editor','user') NOT NULL DEFAULT 'user', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, slug VARCHAR(80) NOT NULL UNIQUE, description VARCHAR(255), icon VARCHAR(40), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE articles(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(200) NOT NULL, slug VARCHAR(220) NOT NULL UNIQUE, excerpt VARCHAR(400), content MEDIUMTEXT NOT NULL, cover_image VARCHAR(255), category_id INT UNSIGNED NULL, author_id INT UNSIGNED NULL, status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', views_count INT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, published_at TIMESTAMP NULL,
 INDEX(status,published_at), FULLTEXT(title,excerpt,content),
 FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL, FOREIGN KEY(author_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE tips(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, description VARCHAR(400) NOT NULL, detailed_content TEXT, icon VARCHAR(40), category_id INT UNSIGNED NULL, display_order INT NOT NULL DEFAULT 0, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE quizzes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, question VARCHAR(400) NOT NULL, option_a VARCHAR(200) NOT NULL, option_b VARCHAR(200) NOT NULL, option_c VARCHAR(200) NOT NULL, option_d VARCHAR(200) NOT NULL, correct_answer ENUM('a','b','c','d') NOT NULL, explanation VARCHAR(400), category_id INT UNSIGNED NULL, difficulty ENUM('easy','medium','hard') NOT NULL DEFAULT 'easy', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE quiz_results(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, quiz_id INT UNSIGNED NOT NULL, selected_answer ENUM('a','b','c','d') NOT NULL, is_correct TINYINT(1) NOT NULL, completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,completed_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE bookmarks(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, article_id INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,article_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE);
CREATE TABLE comments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, article_id INT UNSIGNED NOT NULL, content VARCHAR(1000) NOT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(article_id,status), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE);
CREATE TABLE feedback(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL, message VARCHAR(2000) NOT NULL, rating TINYINT UNSIGNED, status ENUM('new','read','archived') NOT NULL DEFAULT 'new', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE website_settings(id TINYINT UNSIGNED PRIMARY KEY DEFAULT 1, site_name VARCHAR(120) NOT NULL, site_description VARCHAR(255), logo_url VARCHAR(255), contact_email VARCHAR(190), social_links JSON, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);

